import type { FormEvent, ReactNode } from 'react';
import { Link, NavLink, Navigate, Outlet, Route, Routes, useLocation, useNavigate, useParams, useSearchParams } from 'react-router-dom';
import {
  ArrowDownUp, ArrowLeft, ArrowRight, BadgeCheck, Bell, Check, CheckCheck, ChevronDown, ChevronLeft,
  ChevronRight, CircleHelp, Clock3, Compass, Filter, Heart, Home, KeyRound, LoaderCircle, LockKeyhole,
  LogOut, Mail, MapPin, Menu, MessageCircle, MessageSquare, Moon, MoreHorizontal, Package, Plus,
  Search, Send, Settings2, ShieldCheck, ShoppingBag, SlidersHorizontal, Sparkles, Sun, Trash2,
  UserRound, X, Zap,
} from 'lucide-react';
import {
  ApiError, clearTokens, DEMO_ITEMS, DEVICE, fetchCategories, fetchListing, fetchSellerListings,
  getAccessToken, getSavedItems, getUserId, GQL, graphql, isSaved, money, normalizeListing,
  persistTokens, publicPost, saveListing, searchListings, STATIC_CATEGORIES,
} from './lib/api';
